function MessageTextPart({
  part,
  message,
}: {
  part: MessagePartsPart
  message: MessagePartsMessage
}) {
  if (part.type !== "text") {
    return null
  }

  return (
    <Bubble
      align={message.role === "user" ? "end" : "start"}
      variant={message.role === "user" ? "default" : "ghost"}
    >
      <BubbleContent>
        <span class="whitespace-pre-wrap">{part.text}</span>
      </BubbleContent>
    </Bubble>
  )
}

